// src/components/ui/ClientModal.js
import React, { useState } from 'react';
import { clientsAPI } from '../../services/api';
import { X } from 'lucide-react';

export default function ClientModal({ client, onClose, onSave }) {
  const [form, setForm] = useState({
    name: client?.name || '',
    phone: client?.phone || '',
    address: client?.address || '',
    email: client?.email || '',
  });
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError('');
    try {
      if (client) {
        await clientsAPI.update(client._id, form);
      } else {
        await clientsAPI.create(form);
      }
      onSave();
    } catch (err) {
      setError(err.response?.data?.message || 'Erreur');
    }
    setLoading(false);
  };

  return (
    <div className="modal-backdrop" onClick={(e) => e.target === e.currentTarget && onClose()}>
      <div className="modal fade-in">
        <div className="modal-header">
          <h3>{client ? 'Modifier le client' : 'Nouveau client'}</h3>
          <button onClick={onClose} className="btn btn-icon btn-outline"><X size={15} /></button>
        </div>
        <form onSubmit={handleSubmit}>
          <div className="modal-body">
            {error && <div className="alert alert-danger">{error}</div>}
            <div className="form-group">
              <label>Nom complet *</label>
              <input className="form-control" value={form.name}
                onChange={e => setForm({ ...form, name: e.target.value })} required placeholder="Ali Traoré" />
            </div>
            <div className="form-group">
              <label>Téléphone *</label>
              <input className="form-control" value={form.phone}
                onChange={e => setForm({ ...form, phone: e.target.value })} required placeholder="+226 70 00 00 01" />
            </div>
            <div className="form-group">
              <label>Adresse *</label>
              <input className="form-control" value={form.address}
                onChange={e => setForm({ ...form, address: e.target.value })} required placeholder="Ouagadougou, Secteur 15" />
            </div>
            <div className="form-group" style={{ marginBottom: 0 }}>
              <label>Email (optionnel)</label>
              <input className="form-control" type="email" value={form.email}
                onChange={e => setForm({ ...form, email: e.target.value })} placeholder="client@example.com" />
            </div>
          </div>
          <div className="modal-footer">
            <button type="button" onClick={onClose} className="btn btn-outline">Annuler</button>
            <button type="submit" className="btn btn-primary" disabled={loading}>
              {loading ? 'Enregistrement...' : (client ? 'Modifier' : 'Créer')}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}
